package tpllite

import (
	"errors"
	"strconv"
	"strings"
	"unicode/utf8"
)

const ws = " \t\n\r"

var errBad = errors.New("tpllite: bad input")

func isName(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		alpha := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
		digit := (c >= '0' && c <= '9') || c == '.'
		if i == 0 && !alpha {
			return false
		}
		if !alpha && !digit {
			return false
		}
	}
	return true
}

func parseVars(items []string) (map[string]string, error) {
	env := map[string]string{}
	for _, item := range items {
		k, v, ok := strings.Cut(item, "=")
		if !ok || !isName(k) {
			return nil, errBad
		}
		env[k] = v
	}
	return env, nil
}

type part struct {
	expr bool
	text string
}

func scan(t string) ([]part, error) {
	var parts []part
	var buf strings.Builder
	i := 0
	for i < len(t) {
		switch {
		case strings.HasPrefix(t[i:], "\\{{"):
			buf.WriteString("{{")
			i += 3
		case strings.HasPrefix(t[i:], "{{"):
			end := strings.Index(t[i+2:], "}}")
			if end < 0 {
				return nil, errBad
			}
			if buf.Len() > 0 {
				parts = append(parts, part{false, buf.String()})
				buf.Reset()
			}
			parts = append(parts, part{true, t[i+2 : i+2+end]})
			i += 2 + end + 2
		default:
			buf.WriteByte(t[i])
			i++
		}
	}
	if buf.Len() > 0 {
		parts = append(parts, part{false, buf.String()})
	}
	return parts, nil
}

func parseExpr(text string) (string, []string, error) {
	pieces := strings.Split(text, "|")
	for i := range pieces {
		pieces[i] = strings.Trim(pieces[i], ws)
		if pieces[i] == "" {
			return "", nil, errBad
		}
	}
	if !isName(pieces[0]) {
		return "", nil, errBad
	}
	return pieces[0], pieces[1:], nil
}

func asciiMap(s string, up bool) string {
	b := []byte(s)
	for i, c := range b {
		if up && c >= 'a' && c <= 'z' {
			b[i] = c - 32
		} else if !up && c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}

func apply(value, f string) (string, error) {
	name, arg, hasArg := strings.Cut(f, ":")
	switch name {
	case "upper", "lower", "trim", "len":
		if hasArg {
			return "", errBad
		}
		switch name {
		case "upper":
			return asciiMap(value, true), nil
		case "lower":
			return asciiMap(value, false), nil
		case "trim":
			return strings.Trim(value, ws), nil
		}
		return strconv.Itoa(utf8.RuneCountInString(value)), nil
	case "pad":
		a := strings.Trim(arg, ws)
		if !hasArg || len(a) < 1 || len(a) > 2 || a[0] < '1' || a[0] > '9' || (len(a) == 2 && (a[1] < '0' || a[1] > '9')) {
			return "", errBad
		}
		n, _ := strconv.Atoi(a)
		if have := utf8.RuneCountInString(value); have < n {
			return strings.Repeat(" ", n-have) + value, nil
		}
		return value, nil
	case "default":
		if !hasArg {
			return "", errBad
		}
		return value, nil
	}
	return "", errBad
}

func Render(template string, vars []string) (string, error) {
	env, err := parseVars(vars)
	if err != nil {
		return "", err
	}
	parts, err := scan(template)
	if err != nil {
		return "", err
	}
	var out strings.Builder
	for _, p := range parts {
		if !p.expr {
			out.WriteString(p.text)
			continue
		}
		name, filters, err := parseExpr(p.text)
		if err != nil {
			return "", err
		}
		value, ok := env[name]
		if !ok {
			if len(filters) == 0 {
				return "", errBad
			}
			fname, farg, has := strings.Cut(filters[0], ":")
			if fname != "default" || !has {
				return "", errBad
			}
			value = strings.Trim(farg, ws)
		}
		for _, f := range filters {
			if value, err = apply(value, f); err != nil {
				return "", err
			}
		}
		out.WriteString(value)
	}
	return out.String(), nil
}

func CountPlaceholders(template string) (int64, error) {
	parts, err := scan(template)
	if err != nil {
		return 0, err
	}
	var n int64
	for _, p := range parts {
		if p.expr {
			if _, _, err := parseExpr(p.text); err != nil {
				return 0, err
			}
			n++
		}
	}
	return n, nil
}

func Names(template string) ([]string, error) {
	parts, err := scan(template)
	if err != nil {
		return nil, err
	}
	out := []string{}
	seen := map[string]bool{}
	for _, p := range parts {
		if p.expr {
			name, _, err := parseExpr(p.text)
			if err != nil {
				return nil, err
			}
			if !seen[name] {
				seen[name] = true
				out = append(out, name)
			}
		}
	}
	return out, nil
}

